(date '2026-12-31','Martyrs Sevastiana Mediolanskogo and druzhiny ego: Nikostrata kaznokhranitelya, zheny ego Zoi, Kastoriya, Trankvillina, Priest, and synov ego Markellina and Marka, diakonov, Klavdiya, nachalnika nad tyurmami, syna ego Simforiana, brata Viktorina, Tivurtiya and Kastula (ca. 287); Venerable Sevastiana Sokhotskogo, Poshekhonskogo (ca. 1500); proslavlenie Righteous Simeona Verkhoturskogo (Merkushinskogo) (1694); Saint Hierarch Modesta, patriarkha Ierusalimskogo (633–634); Venerable Flora, Bishop Amiiskogo (VII); Venerable Mikhaila Singella, Confessor (ca. 845); Venerable Daniila Pustynnika, ieroskhimonakha (Romanian); Martyr Viktora Matveeva (1937); Hieromartyrs Faddeya (Uspenskogo), arkhiBishop Tverskogo and Kashinskogo, Nikolaya (Klementeva), arkhiBishop Velikoustyuzhskogo, Ilii Benemanskogo, Ioanna Mironskogo, Vladimira Preobrazhenskogo and Nikolaya Kobranova, Priests (1937); Hieromartyr Sergiya Astakhova, diakona and Martyr Very Truks (1942)','Pravoslavnyi tserkovnyi kalendar na 31 dekabrya 2026 goda (chetverg) - Week 31-ya after Pentecost. Martyrs Sevastiana Mediolanskogo and druzhiny ego: Nikostrata kaznokhranitelya, zheny ego Zoi, Kastoriya, Trankvillina, Priest, and synov ego Markellina and Marka, diakonov, Klavdiya, nachalnika nad tyurmami, syna ego Simforiana, brata Viktorina, Tivurtiya and Kastula (ca. 287). Spisok vsekh tserkovnykh prazdnikov and sobytii otmechaemykh v etu datu.','Rozhdestvenskii post')
)
insert into public.calendar_day_translations (
  calendar_day_id, language_code, title, saints, details, fasting_note
)
select d.id, 'en', p.title, d.saints, p.details, p.fasting_note
from payload p
join public.calendar_days d
  on d.country_code = 'BY'
 and d.calendar_code = 'by-belarusian-orthodox-church'
 and d.language_code = 'ru'
 and d.calendar_date = p.calendar_date
on conflict (calendar_day_id, language_code) do update set
  title = excluded.title,
  saints = excluded.saints,
  details = excluded.details,
  fasting_note = excluded.fasting_note,
  updated_at = timezone('utc', now());

do $$
declare
  translation_count integer;
begin
  select count(*)
    into translation_count
  from public.calendar_days d
  join public.calendar_day_translations t on t.calendar_day_id = d.id
  where d.country_code = 'BY'
    and d.calendar_code = 'by-belarusian-orthodox-church'
    and d.language_code = 'ru'
    and d.calendar_date between date '2026-01-01' and date '2026-12-31'
    and t.language_code = 'en';

  if translation_count <> 365 then
    raise exception 'Expected 365 BY English translations; found %', translation_count;
  end if;
end
$$;

commit;
